CREATE TABLE public.woic_reasoning_reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agency_id uuid NOT NULL REFERENCES public.agencies(id), trace_id uuid NOT NULL REFERENCES public.woic_reasoning_traces(id), requested_by uuid NOT NULL, status text NOT NULL DEFAULT 'running', result jsonb, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.woic_reasoning_reviews TO authenticated;
GRANT ALL ON public.woic_reasoning_reviews TO service_role;
ALTER TABLE public.woic_reasoning_reviews ENABLE ROW LEVEL SECURITY;
CREATE POLICY reviews_read ON public.woic_reasoning_reviews FOR SELECT TO authenticated USING (private.has_role(auth.uid(),'super_admin') OR (private.has_role(auth.uid(),'agency_admin') AND EXISTS(SELECT 1 FROM public.agency_members am WHERE am.agency_id=woic_reasoning_reviews.agency_id AND am.user_id=auth.uid() AND am.is_active)));
CREATE TRIGGER reviews_updated BEFORE UPDATE ON public.woic_reasoning_reviews FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE INDEX reviews_agency_created ON public.woic_reasoning_reviews(agency_id,created_at DESC);
CREATE UNIQUE INDEX one_running_review ON public.woic_reasoning_reviews(agency_id,trace_id) WHERE status='running';
CREATE TABLE public.woic_reasoning_review_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), agency_id uuid NOT NULL REFERENCES public.agencies(id), review_id uuid NOT NULL REFERENCES public.woic_reasoning_reviews(id), actor_id uuid NOT NULL, capability text NOT NULL, item_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(review_id,capability,item_id));
GRANT SELECT ON public.woic_reasoning_review_actions TO authenticated;
GRANT ALL ON public.woic_reasoning_review_actions TO service_role;
ALTER TABLE public.woic_reasoning_review_actions ENABLE ROW LEVEL SECURITY;
CREATE POLICY review_actions_read ON public.woic_reasoning_review_actions FOR SELECT TO authenticated USING (private.has_role(auth.uid(),'super_admin') OR (private.has_role(auth.uid(),'agency_admin') AND EXISTS(SELECT 1 FROM public.agency_members am WHERE am.agency_id=woic_reasoning_review_actions.agency_id AND am.user_id=auth.uid() AND am.is_active)));
CREATE TABLE public.woic_reasoning_gateway_state (agency_id uuid PRIMARY KEY REFERENCES public.agencies(id), status integer NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.woic_reasoning_gateway_state TO authenticated;
GRANT ALL ON public.woic_reasoning_gateway_state TO service_role;
ALTER TABLE public.woic_reasoning_gateway_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY gateway_state_read ON public.woic_reasoning_gateway_state FOR SELECT TO authenticated USING (private.has_role(auth.uid(),'super_admin') OR (private.has_role(auth.uid(),'agency_admin') AND EXISTS(SELECT 1 FROM public.agency_members am WHERE am.agency_id=woic_reasoning_gateway_state.agency_id AND am.user_id=auth.uid() AND am.is_active)));
NOTIFY pgrst,'reload schema';